"""Household v2: single-source story, evidence, handovers, hints and print recipes."""
import json,re
from pathlib import Path
def clean(text):
 text=re.sub(r'(?<=[a-z])(?=\d)',' ',str(text))
 text=re.sub(r'\b(ACT|ACTS)(?=\d)',r'\1 ',text)
 return re.sub(r'\b(seal|draft|counter|bag)(?=[A-Z]\d)',r'\1 ',text)
def p(text):return dict(type='p',text=clean(text))
def box(title,text):return dict(type='box',title=clean(title),text=clean(text))
def table(head,rows):return dict(type='table',head=[clean(x)for x in head],rows=[[clean(x)for x in row]for row in rows])
def lines(labels):return dict(type='lines',labels=[clean(x)for x in labels])
def scene(kind,height=140):return dict(type='scene',kind=kind,height=height)
def page(n,code,title,*blocks):return dict(n=n,code=code,title=title,blocks=list(blocks))
